# Let me visualize the output grid as a binary mask
positions_5 = [(0, 3), (1, 0), (1, 1), (1, 2), (1, 3), (1, 5), (2, 0), (2, 1), (2, 5), (4, 1), (4, 5), (5, 0), (5, 1), (5, 3), (5, 4), (5, 5), (6, 3), (7, 1), (7, 2), (7, 3), (8, 1), (8, 4), (8, 5), (9, 0), (9, 1), (9, 4), (9, 5), (10, 2), (10, 3), (10, 4), (10, 5), (11, 2), (12, 5)]
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

print("Binary view of output (1=not 2, so includes 5 and 8):")
for r in range(13):
    line = ''.join('1' if demo_output[r][c] != 2 else '0' for c in range(6))
    print(line)

print("\nPositions of 8:")
for r in range(13):
    line = ''
    for c in range(6):
        if demo_output[r][c] == 8:
            line += 'X'
        else:
            line += '.'
    print(line)

# Look at column by column patterns
for c in range(6):
    print(f"Column {c}:")
    for r in range(13):
        print(f"  ({r},{c})={demo_output[r][c]}", end='')
    print()

# Visualize more clearly
positions_5 = set(demo_output[r][c] == 5 for r in range(13) for c in range(6))
positions_5_coords = [(r,c) for r in range(13) for c in range(6) if demo_output[r][c] == 5]
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

print("Overlay view:")
print("  5=blue cell, 8=X, .=background")
for r in range(13):
    line = []
    for c in range(6):
        if (r,c) in positions_8:
            line.append('X')
        elif (r,c) in positions_5_coords:
            line.append('#')  # Mark as 5
        else:
            line.append('.')
    print(f"{line}")

# What cells are diagonally adjacent to any 8?
diag_adjacent = set()
for pr, pc in positions_8:
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = pr + dr, pc + dc
            if 0 <= nr < 13 and 0 <= nc < 6:
                diag_adjacent.add((nr, nc))

print("\nDiagonally adjacent to 8s:", sorted(diag_adjacent))
print("Overlap with 5s:", len(diag_adjacent & set(positions_5_coords)))

# Test hypothesis: cell becomes 5 if itself or a neighbor is on a line from any 8
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

def would_be_5(r,c):
    # Check if cell is on cardinal/diagonal line from any 8
    for pr, pc in positions_8:
        if r == pr or c == pc or abs(r-pr) == abs(c-pc):
            return True
    # Check if any neighbor is
    neighbors = [(r-1,c),(r+1,c),(r,c-1),(r,c+1)] + [(r-1,c-1),(r-1,c+1),(r+1,c-1),(r+1,c+1)]
    for nr, nc in neighbors:
        if 0 <= nr < 13 and 0 <= nc < 6:
            for pr, pc in positions_8:
                if nr == pr or nc == pc or abs(nr-pr) == abs(nc-pc):
                    return True
    return False

print("Testing hypothesis:")
all_match = True
mismatches = []
for r in range(13):
    for c in range(6):
        expected = 5 if would_be_5(r,c) else demo_input[r][c]
        actual = demo_output[r][c]
        if expected != actual:
            all_match = False
            mismatches.append(((r,c), expected, actual))

print(f"All match: {all_match}")
if not all_match:
    print(f"Mismatches ({len(mismatches)}):")
    for p, exp, act in mismatches[:10]:
        print(f"  {p}: expected={exp}, actual={act}")

# Try checking: cell becomes 5 if it's on exactly 1 diagonal from some 8
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

count_on_diag = {}
for r in range(13):
    for c in range(6):
        count = sum(1 for pr, pc in positions_8 if abs(r-pr) == abs(c-pc))
        if 0 <= count <= 2:  # Interesting counts
            count_on_diag[(r,c)] = count

print("Cells with 1 or 2 diagonal connections to 8s:")
for p, cnt in sorted(count_on_diag.items()):
    if demo_output[p[0]][p[1]] == 5:
        print(f"{p}: {cnt} diagonal(s)")

# Final attempt: build expected output by marking cells along lines from each 8
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]
directions = [(-1,0),(1,0),(0,-1),(0,1)]  # cardinal directions

expected = [[demo_input[r][c] for c in range(6)] for r in range(13)]

def should_be_marked(r,c,pos):
    """Check if cell is on line from position pos"""
    pr, pc = pos

    # Cardinal directions
    for dr, dc in directions:
        nr, nc = r, c
        while True:
            nr, nc = nr + dr, nc + dc
            if not (0 <= nr < 13 and 0 <= nc < 6):
                break
            # Check if we hit the starting position
            if (nr, nc) == (pr, pc):
                return True
            # Don't continue past another 8
            if expected[nr][nc] == 8:
                break
            # Continue along this direction
            pass
    # Diagonal directions
    diag_dirs = [(-1,-1),(-1,1),(1,-1),(1,1)]
    for dr, dc in diag_dirs:
        nr, nc = r, c
        while True:
            nr, nc = nr + dr, nc + dc
            if not (0 <= nr < 13 and 0 <= nc < 6):
                break
            if (nr, nc) == (pr, pc):
                return True
            if expected[nr][nc] == 8:
                break
            pass
    return False

# Mark cells that should be 5
for r in range(13):
    for c in range(6):
        for pr, pc in positions_8:
            if demo_output[r][c] == 5 and demo_input[r][c] == 2:
                if should_be_marked(r,c,(pr,pc)):
                    print(f"{(r,c)} is on line from {(pr,pc)}")
                    break

# Find which 5s are NOT on any cardinal/diagonal line from an 8
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

def is_on_line_from(r,c,pos):
    """Check if cell is on ANY line (cardinal or diagonal) from position pos"""
    pr, pc = pos
    # Cardinal directions - going away from source
    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
        nr, nc = r, c
        while True:
            # Go backwards from current cell
            prev_nr, prev_nc = nr - dr, nc - dc
            if abs(prev_nr - pr) == 0 and abs(prev_nc - pc) == 0:
                return True
            nr, nc = prev_nr, prev_nc
            if not (0 <= nr < 13 and 0 <= nc < 6):
                break
            if expected[nr][nc] == 8 and (nr != pr or nc != pc):
                break
    # Diagonal directions
    for dr, dc in [(1,1),(1,-1),(-1,1),(-1,-1)]:
        nr, nc = r, c
        while True:
            prev_nr, prev_nc = nr - dr, nc - dc
            if abs(prev_nr - pr) == abs(prev_nc - pc):
                return True
            nr, nc = prev_nr, prev_nc
            if not (0 <= nr < 13 and 0 <= nc < 6):
                break
    return False

not_covered = []
for r in range(13):
    for c in range(6):
        if demo_output[r][c] == 5 and demo_input[r][c] == 2:
            if not any(is_on_line_from(r,c,p) for p in positions_8):
                not_covered.append((r,c))

print("5s not on any line from any 8:")
print(not_covered)

# Check Manhattan distances from each cell to nearest 8
positions_8 = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

max_dist_in_fives = max(abs(r-pr) + abs(c-pc) for r,c in [(0,3),(1,0),(1,1),(1,2),(1,3),(1,5),(2,0),(2,1),(2,5),(4,1),(4,5),(5,0),(5,1),(5,3),(5,4),(5,5),(6,3),(7,1),(7,2),(7,3),(8,1),(8,4),(8,5),(9,0),(9,1),(9,4),(9,5),(10,2),(10,3),(10,4),(10,5),(11,2),(12,5)] for pr,pc in positions_8 for _ in [1])  # Just get structure

# Actually compute it properly
def manhattan_to_nearest(r,c):
    return min(abs(r-pr) + abs(c-pc) for pr,pc in positions_8)

print("Max Manhattan dist to any 5:")
fives = [(r,c) for r in range(13) for c in range(6) if demo_output[r][c] == 5]
max_dist = max(manhattan_to_nearest(r,c) for r,c in fives)
print(f"Max: {max_dist}")

# Are there non-5s closer than some threshold?
closer_non_5s = []
for r in range(13):
    for c in range(6):
        if demo_output[r][c] != 5 and demo_input[r][c] == 2:
            if manhattan_to_nearest(r,c) < max_dist:
                closer_non_5s.append((r,c,manhattan_to_nearest(r,c)))

if closer_non_5s:
    print(f"Closer non-5s: {closer_non_5s[:10]}")
else:
    print("All non-5s have equal or higher distance than max 5")

